/**
 * Página de Conferência & Recebimento — exclusiva para lojistas.
 *
 * Hub com as DUAS ações da loja (as opções que já existiam):
 *  - Acompanhar expedição → rastreia onde está a entrega (StoreExpeditionTracker).
 *  - Conferir chegada     → vai para /requisicoes/chegada, onde a loja bipa as
 *    etiquetas da requisição que chegou e dá entrada no estoque.
 *
 * Mesma gramática visual de ProduçãoDiária: fundo branco + decorações inline
 * (toldo, folhas, glows), SEM bege, SEM MommaPageLayout. Não lista/carrega
 * requisições aqui — isso é responsabilidade da página de chegada.
 *
 * Loja ativa: StoreContext → selectedStore.
 */
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Truck,
  ScanBarcode,
  Leaf,
  ChevronRight,
  Loader2,
  Package,
  Clock,
} from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "sonner";

import { Badge } from "@/shared/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/shared/ui/dialog";
import { supabase } from "@/integrations/supabase/client";
import { useStore } from "@/shared/contexts/StoreContext";
import { StoreExpeditionTracker } from "@/features/logistica";

interface ExpedicaoRow {
  id: string;
  status: string;
  code: string | null;
  veiculo: string | null;
  created_at: string;
}

const EXPEDICAO_STATUS_ATIVOS = [
  "separation",
  "loading",
  "dispatch",
  "in_transit",
  "unloading",
];

const STATUS_LABEL: Record<string, string> = {
  separation: "Em separação",
  loading: "Carregando",
  dispatch: "Despachada",
  in_transit: "Em trânsito",
  unloading: "Descarregando",
};

function fmtDateTime(iso: string): string {
  try {
    return format(new Date(iso), "dd/MM 'às' HH:mm", { locale: ptBR });
  } catch {
    return iso;
  }
}

export function ConferenciaRecebimentoPage() {
  const navigate = useNavigate();
  const { selectedStore } = useStore();

  const [buscandoExpedicoes, setBuscandoExpedicoes] = useState(false);
  const [expedicoes, setExpedicoes] = useState<ExpedicaoRow[]>([]);
  const [seletorAberto, setSeletorAberto] = useState(false);
  const [trackerExpId, setTrackerExpId] = useState<string | null>(null);

  const storeName = selectedStore?.shortName || selectedStore?.name || "";

  const handleAcompanharExpedicao = async () => {
    setBuscandoExpedicoes(true);
    try {
      const { data, error } = await supabase
        .from("expedicoes")
        .select("id, status, code, veiculo, created_at")
        .in("status", EXPEDICAO_STATUS_ATIVOS)
        .order("created_at", { ascending: false });
      if (error) throw error;
      if (!data || data.length === 0) {
        toast.info("Nenhuma expedição em andamento no momento.");
        return;
      }
      setExpedicoes(data as ExpedicaoRow[]);
      setSeletorAberto(true);
    } catch {
      toast.error("Erro ao buscar expedições. Tente novamente.");
    } finally {
      setBuscandoExpedicoes(false);
    }
  };

  const handleSelecionarExpedicao = (id: string) => {
    setTrackerExpId(id);
    setSeletorAberto(false);
  };

  return (
    <div className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-x-hidden transition-colors duration-300">
      {/* Faixa de toldo (topo) */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm" />

      {/* Folhas decorativas no fundo */}
      <div
        className="fixed top-[-5%] right-[-10%] md:right-[-5%] w-[300px] md:w-[500px] h-[300px] md:h-[500px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
        style={{ animationDuration: "10s" }}
      >
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div
        className="fixed bottom-[-10%] left-[-15%] md:left-[-5%] w-[400px] md:w-[600px] h-[400px] md:h-[600px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
        style={{ animationDuration: "12s" }}
      >
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>

      {/* Brilhos ambientes */}
      <div className="fixed top-[20%] left-[10%] w-[200px] md:w-[400px] h-[200px] md:h-[400px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
      <div className="fixed bottom-[30%] right-[10%] w-[250px] md:w-[500px] h-[250px] md:h-[500px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

      <div className="relative z-10 w-full max-w-5xl mx-auto space-y-8 px-4 sm:px-6 py-6 md:py-10 animate-in fade-in duration-500">
        {/* Header */}
        <div className="flex items-center gap-3 sm:gap-4">
          <div className="h-12 w-12 sm:h-14 sm:w-14 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 flex items-center justify-center shrink-0">
            <Package className="h-6 w-6 sm:h-7 sm:w-7 text-[#57715B] dark:text-[#E6DCCF]" />
          </div>
          <div>
            <h1 className="text-3xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif drop-shadow-sm">
              Conferência &amp; Recebimento
            </h1>
            <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80">
              {storeName ? `${storeName} · ` : ""}Acompanhe e receba as entregas da fábrica
            </p>
          </div>
        </div>

        {/* Duas opções */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
          {/* Acompanhar expedição */}
          <button
            data-mia-action="acompanhar-expedicao"
            type="button"
            onClick={handleAcompanharExpedicao}
            disabled={buscandoExpedicoes}
            className="group relative overflow-hidden text-left rounded-[2rem] border border-[#57715B]/10 dark:border-white/10 bg-white/60 dark:bg-black/20 backdrop-blur-xl shadow-sm hover:shadow-md hover:border-[#57715B]/25 transition-all duration-300 p-6 sm:p-8 disabled:opacity-70 min-h-[44px]"
          >
            <div className="absolute -top-6 -right-6 opacity-[0.06] group-hover:opacity-10 transition-opacity pointer-events-none">
              <Truck className="h-28 w-28 text-[#57715B]" />
            </div>
            <div className="relative flex flex-col gap-4">
              <div className="h-14 w-14 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
                {buscandoExpedicoes ? (
                  <Loader2 className="h-7 w-7 text-[#57715B] animate-spin" />
                ) : (
                  <Truck className="h-7 w-7 text-[#57715B]" />
                )}
              </div>
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                  Acompanhar expedição
                </h2>
                <p className="text-sm text-muted-foreground mt-1">
                  Veja onde está a entrega da sua loja em tempo real.
                </p>
              </div>
              <div className="flex items-center gap-1 text-sm font-semibold text-[#57715B] dark:text-[#8FAE94]">
                Acompanhar
                <ChevronRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />
              </div>
            </div>
          </button>

          {/* Conferir chegada */}
          <button
            data-mia-action="conferir-chegada"
            type="button"
            onClick={() => navigate("/requisicoes/chegada")}
            className="group relative overflow-hidden text-left rounded-[2rem] border border-[#57715B]/10 dark:border-white/10 bg-white/60 dark:bg-black/20 backdrop-blur-xl shadow-sm hover:shadow-md hover:border-[#57715B]/25 transition-all duration-300 p-6 sm:p-8 min-h-[44px]"
          >
            <div className="absolute -top-6 -right-6 opacity-[0.06] group-hover:opacity-10 transition-opacity pointer-events-none">
              <ScanBarcode className="h-28 w-28 text-[#57715B]" />
            </div>
            <div className="relative flex flex-col gap-4">
              <div className="h-14 w-14 rounded-2xl bg-[#57715B]/10 flex items-center justify-center">
                <ScanBarcode className="h-7 w-7 text-[#57715B]" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                  Conferir chegada
                </h2>
                <p className="text-sm text-muted-foreground mt-1">
                  Bipe as etiquetas da requisição que chegou e dê entrada no estoque.
                </p>
              </div>
              <div className="flex items-center gap-1 text-sm font-semibold text-[#57715B] dark:text-[#8FAE94]">
                Conferir
                <ChevronRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />
              </div>
            </div>
          </button>
        </div>
      </div>

      {/* Seletor de expedição */}
      <Dialog open={seletorAberto} onOpenChange={setSeletorAberto}>
        <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-[#2D362E] dark:text-[#E6DCCF]">
              <Truck className="h-5 w-5 text-[#57715B]" /> Selecionar expedição
            </DialogTitle>
            <DialogDescription>
              Escolha qual expedição deseja acompanhar.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-3 max-h-[400px] overflow-y-auto py-1">
            {expedicoes.map((exp) => (
              <button
                data-mia-skip
                key={exp.id}
                type="button"
                onClick={() => handleSelecionarExpedicao(exp.id)}
                className="w-full text-left p-4 rounded-xl border border-[#57715B]/10 dark:border-white/10 hover:border-[#57715B]/30 hover:bg-[#57715B]/5 transition-all"
              >
                <div className="flex items-center justify-between mb-2 gap-2">
                  <Badge
                    variant="outline"
                    className="font-mono text-xs border-[#57715B]/20 text-[#57715B] dark:text-[#8FAE94]"
                  >
                    {exp.code || `EXP-${exp.id.slice(0, 8).toUpperCase()}`}
                  </Badge>
                  <Badge className="bg-[#57715B]/10 text-[#57715B] dark:text-[#8FAE94] border-0 text-xs">
                    {STATUS_LABEL[exp.status] || exp.status}
                  </Badge>
                </div>
                <div className="flex items-center gap-3 text-xs text-muted-foreground">
                  {exp.veiculo && (
                    <span className="flex items-center gap-1">
                      <Truck className="h-3 w-3" />
                      {exp.veiculo}
                    </span>
                  )}
                  <span className="flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    {fmtDateTime(exp.created_at)}
                  </span>
                </div>
              </button>
            ))}
          </div>
        </DialogContent>
      </Dialog>

      {/* Rastreamento da expedição escolhida */}
      {trackerExpId && (
        <StoreExpeditionTracker
          isOpen
          onClose={() => setTrackerExpId(null)}
          expeditionId={trackerExpId}
          storeName={storeName}
        />
      )}
    </div>
  );
}

export default ConferenciaRecebimentoPage;

