/* Mia Chat Design System — vars --mia-* centralizadas (rose rubi, tipografia) */
@import './features/mia/styles/mia-chat.css';

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Leaflet Map Styles */
.leaflet-container {
  height: 100%;
  width: 100%;
  z-index: 1;
}

.leaflet-control-container {
  z-index: 1000;
}

.leaflet-popup-content-wrapper {
  border-radius: 8px;
}

.leaflet-popup-tip {
  background: white;
}

/* Momma Design System - Cores e estilos baseados na identidade visual */

@layer base {
  :root {
    /* Sistema de cores Pantone da empresa - Modo Claro */
    /* Cores Pantone convertidas para HSL (regra 70-20-10 aprimorada) */
    --pantone-primary: 35 33% 55%;    /* #B49364 - Marrom dourado (20%) */
    --pantone-background: 46 63% 95%; /* #F3ECD4 - Bege claro (70%) */
    --pantone-accent: 133 17% 33%;    /* #33733F - Verde escuro (10%) */
    --pantone-foreground: 60 7% 20%;   /* #3C3B34 - Cinza escuro (texto) */

    /* Sistema de cores baseado na regra 70-20-10 (sem verde oliva) */

